def compute(vars):
    try:
        change_dollars = vars["v2"] - vars["v1"]
        change_millions = change_dollars / 1000000
        return {
            "value": change_millions,
            "trace": {
                "change_dollars": change_dollars,
                "output_meta": {
                    "currency": "USD",
                    "scale": "millions",
                    "unit": "currency"
                }
            }
        }
    except ZeroDivisionError:
        return None
